    <AuthenticatedLayout>
        <template #header>
            <div class="flex items-center justify-between gap-4">
                <div><h2 class="text-xl font-semibold">{{ event.title }}</h2><p class="text-sm text-gray-600">{{ label(event.status) }}</p></div>
                <div class="flex flex-wrap gap-2"><Link :href="route('events.index')" class="rounded border border-gray-300 px-3 py-2 text-sm">Back to Events</Link><Link :href="route('events.invitation.edit', event.id)" class="rounded border border-gray-300 px-3 py-2 text-sm">Invitation</Link><Link :href="route('events.activities.index', event.id)" class="rounded border border-gray-300 px-3 py-2 text-sm">Schedule</Link><Link v-if="canViewGuests" :href="route('events.guests.index', event.id)" class="rounded border border-gray-300 px-3 py-2 text-sm">Guests</Link><Link v-if="canViewRsvps" :href="route('events.rsvps.index', event.id)" class="rounded border border-gray-300 px-3 py-2 text-sm">RSVPs</Link><Link v-if="canEdit" :href="route('events.edit', event.id)" class="rounded bg-indigo-600 px-3 py-2 text-sm text-white">Edit Event</Link></div>
            </div>
        </template>

