            <section class="rounded bg-white p-6 shadow sm:rounded-lg"><h3 class="mb-4 text-lg font-semibold">Date &amp; Time</h3><dl class="grid gap-4 sm:grid-cols-2"><div><dt class="text-sm text-gray-500">Main date</dt><dd>{{ date(event.main_date) }}</dd></div><div><dt class="text-sm text-gray-500">RSVP deadline</dt><dd>{{ date(event.rsvp_deadline) }}</dd></div><div><dt class="text-sm text-gray-500">Start time</dt><dd>{{ value(event.start_time) }}</dd></div><div><dt class="text-sm text-gray-500">End time</dt><dd>{{ value(event.end_time) }}</dd></div><div class="sm:col-span-2"><dt class="text-sm text-gray-500">Event timezone</dt><dd>{{ value(event.event_timezone) }}</dd></div></dl></section>

            <section class="rounded bg-white p-6 shadow sm:rounded-lg"><div class="mb-4 flex items-center justify-between gap-3"><h3 class="text-lg font-semibold">Schedule</h3><Link :href="route('events.activities.index', event.id)" class="text-sm text-indigo-600 underline">View schedule</Link></div><div v-if="activities.length" class="space-y-3"><article v-for="activity in activities" :key="activity.id" class="rounded border p-4"><div class="flex flex-wrap items-start justify-between gap-2"><div><h4 class="font-medium">{{ activity.title }}</h4><p v-if="activity.activity_type" class="text-sm capitalize text-gray-600">{{ label(activity.activity_type) }}</p></div><span class="rounded bg-gray-100 px-2 py-1 text-xs">{{ activity.is_active ? 'Active' : 'Inactive' }}</span></div><p class="mt-2 text-sm text-gray-700">{{ activity.date }} · {{ activity.start_time }}<span v-if="activity.end_time"> – <span v-if="activity.end_date !== activity.date">{{ activity.end_date }}, </span>{{ activity.end_time }}</span></p><p v-if="activity.venue || activity.address" class="mt-1 text-sm text-gray-600">{{ activity.venue || 'Location to be confirmed' }}<span v-if="activity.address"> · {{ activity.address }}</span></p><a v-if="activity.location_url" :href="activity.location_url" target="_blank" rel="noopener noreferrer" class="mt-2 inline-block text-sm text-indigo-600 underline">Open location</a></article></div><p v-else class="text-gray-600">No schedule activities have been added.</p></section>

