            <section class="rounded bg-white p-6 shadow sm:rounded-lg"><h3 class="mb-4 text-lg font-semibold">Guest Information</h3><dl v-if="Object.values(guestInfo).some(Boolean)" class="grid gap-4 sm:grid-cols-2"><div v-if="guestInfo.dress_code"><dt class="text-sm text-gray-500">Dress code</dt><dd class="whitespace-pre-line">{{ guestInfo.dress_code }}</dd></div><div v-if="guestInfo.parking_information"><dt class="text-sm text-gray-500">Parking</dt><dd class="whitespace-pre-line">{{ guestInfo.parking_information }}</dd></div><div v-if="guestInfo.transportation_information"><dt class="text-sm text-gray-500">Transportation</dt><dd class="whitespace-pre-line">{{ guestInfo.transportation_information }}</dd></div><div v-if="guestInfo.accommodation_information"><dt class="text-sm text-gray-500">Accommodation</dt><dd class="whitespace-pre-line">{{ guestInfo.accommodation_information }}</dd></div><div v-if="guestInfo.guest_information" class="sm:col-span-2"><dt class="text-sm text-gray-500">Additional guest information</dt><dd class="whitespace-pre-line">{{ guestInfo.guest_information }}</dd></div></dl><p v-else class="text-gray-600">No guest information provided.</p></section>

